package com.pvpwhgame.hyperoscharge.data

enum class ChargeMode(val key: String, val label: String, val desc: String) {
    BALANCE("balance", "均衡", "温度+电量自适应"),
    FAST("fast", "快充", "目标48°C自学习"),
    FAST_COOLER("fast_cooler", "快充(散热)", "外置散热最大功率"),
    COOL("cool", "冷却", "目标42°C平滑限流");

    companion object {
        fun fromKey(key: String) = entries.find { it.key == key } ?: BALANCE
    }
}

