@Composable
private fun ModeButton(
    mode: ChargeMode,
    isActive: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val bg = if (isActive) Color(0xFF1C2440) else Color(0xFF16161C)
    val border = if (isActive) Color(0xFF7C9DFF) else Color(0xFF2A2A32)
    val textColor = if (isActive) Color(0xFFA9BDFF) else Color(0xFFEEEEEE)

    OutlinedButton(
        onClick = onClick,
        modifier = modifier.height(64.dp),
        shape = RoundedCornerShape(12.dp),
        colors = ButtonDefaults.outlinedButtonColors(containerColor = bg),
        border = BorderStroke(1.dp, border),
        contentPadding = PaddingValues(8.dp)
    ) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
            Text(
                mode.label,
                fontSize = 14.sp,
                fontWeight = FontWeight.SemiBold,
                color = textColor
            )
            Text(
                mode.desc,
                fontSize = 10.sp,
                color = Color(0xFF999999)
            )
        }
    }
}

