package com.pvpwhgame.hyperoscharge.widget

import android.app.PendingIntent
import android.appwidget.AppWidgetManager
import android.appwidget.AppWidgetProvider
import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.graphics.*
import android.widget.RemoteViews
import com.pvpwhgame.hyperoscharge.R
import com.pvpwhgame.hyperoscharge.data.*
import kotlinx.coroutines.*

class ChargeWidgetReceiver : AppWidgetProvider() {

    override fun onUpdate(context: Context, mgr: AppWidgetManager, ids: IntArray) {
        CoroutineScope(Dispatchers.IO).launch {
            val json = ShellExecutor.readFile(ModuleConfig.STATUS_JSON) ?: return@launch
            val status = ChargeStatus.parse(json)

            val csv = ShellExecutor.readFile(ModuleConfig.HISTORY_CSV)
            val history = if (csv != null) HistoryPoint.parseCsv(csv) else emptyList()

            val views = buildViews(context, status, history)
            ids.forEach { mgr.updateAppWidget(it, views) }
        }
    }

    companion object {
        private const val CHART_WIDTH = 600
        private const val CHART_HEIGHT = 200

        fun buildViews(context: Context, status: ChargeStatus, history: List<HistoryPoint>): RemoteViews {
            return RemoteViews(context.packageName, R.layout.widget_charge).apply {
                // 设置状态信息
                setTextViewText(R.id.widget_mode, status.mode.label)
                setTextViewText(R.id.widget_temp, String.format("%.1f°C", status.tempC))
                setTextViewText(R.id.widget_power, String.format("%.1fW", status.powerW))
                setTextViewText(R.id.widget_soc, "${status.soc}%")

                // 设置当前模式按钮高亮
                setInt(R.id.widget_btn_balance, "setBackgroundColor",
                    if (status.mode == ChargeMode.BALANCE) 0xFF7C9DFF.toInt() else 0xFF2A2A32.toInt())
                setInt(R.id.widget_btn_fast, "setBackgroundColor",
                    if (status.mode == ChargeMode.FAST) 0xFF7C9DFF.toInt() else 0xFF2A2A32.toInt())
                setInt(R.id.widget_btn_fast_cooler, "setBackgroundColor",
                    if (status.mode == ChargeMode.FAST_COOLER) 0xFF7C9DFF.toInt() else 0xFF2A2A32.toInt())
                setInt(R.id.widget_btn_cool, "setBackgroundColor",
                    if (status.mode == ChargeMode.COOL) 0xFF7C9DFF.toInt() else 0xFF2A2A32.toInt())

                // 绘制功率图表
                val chartBitmap = drawPowerChart(history)
                setImageViewBitmap(R.id.widget_chart, chartBitmap)

                // 按钮点击 → 切换模式
                setOnClickPendingIntent(R.id.widget_btn_balance, modePending(context, ChargeMode.BALANCE))
                setOnClickPendingIntent(R.id.widget_btn_fast, modePending(context, ChargeMode.FAST))
                setOnClickPendingIntent(R.id.widget_btn_fast_cooler, modePending(context, ChargeMode.FAST_COOLER))
                setOnClickPendingIntent(R.id.widget_btn_cool, modePending(context, ChargeMode.COOL))
            }
        }

        private fun drawPowerChart(history: List<HistoryPoint>): Bitmap {
            val bitmap = Bitmap.createBitmap(CHART_WIDTH, CHART_HEIGHT, Bitmap.Config.ARGB_8888)
            val canvas = Canvas(bitmap)

            // 背景
            canvas.drawColor(0xFF1A1A20.toInt())

            if (history.isEmpty()) {
                // 无数据时显示提示
                val paint = Paint().apply {
                    color = 0xFF666666.toInt()
                    textSize = 24f
                    textAlign = Paint.Align.CENTER
                    isAntiAlias = true
                }
                canvas.drawText("暂无数据", CHART_WIDTH / 2f, CHART_HEIGHT / 2f + 8f, paint)
                return bitmap
            }

            // 获取最近的数据点（最多显示30个点）
            val recentPoints = history.takeLast(30)
            if (recentPoints.size < 2) {
                val paint = Paint().apply {
                    color = 0xFF666666.toInt()
                    textSize = 24f
                    textAlign = Paint.Align.CENTER
                    isAntiAlias = true
                }
                canvas.drawText("数据不足", CHART_WIDTH / 2f, CHART_HEIGHT / 2f + 8f, paint)
                return bitmap
            }

            val powers = recentPoints.map { it.powerW.toFloat() }
            val maxPower = powers.maxOrNull() ?: 50f
            val minPower = 0f
            val powerRange = (maxPower - minPower).coerceAtLeast(1f)

            val padding = 20f
            val chartWidth = CHART_WIDTH - padding * 2
            val chartHeight = CHART_HEIGHT - padding * 2

            // 绘制网格线
            val gridPaint = Paint().apply {
                color = 0xFF2A2A32.toInt()
                strokeWidth = 1f
                style = Paint.Style.STROKE
            }
            for (i in 0..4) {
                val y = padding + chartHeight * i / 4
                canvas.drawLine(padding, y, CHART_WIDTH - padding, y, gridPaint)
            }

            // 绘制功率曲线
            val linePaint = Paint().apply {
                color = 0xFF7C9DFF.toInt()
                strokeWidth = 3f
                style = Paint.Style.STROKE
                isAntiAlias = true
                strokeCap = Paint.Cap.ROUND
                strokeJoin = Paint.Join.ROUND
            }

            val fillPaint = Paint().apply {
                color = 0x307C9DFF.toInt()
                style = Paint.Style.FILL
                isAntiAlias = true
            }

            val path = Path()
            val fillPath = Path()
            val stepX = chartWidth / (recentPoints.size - 1)

            // 计算第一个点的位置
            val firstX = padding
            val firstY = padding + chartHeight * (1 - (powers[0] - minPower) / powerRange)
            path.moveTo(firstX, firstY)
            fillPath.moveTo(firstX, CHART_HEIGHT - padding)
            fillPath.lineTo(firstX, firstY)

            // 绘制曲线
            for (i in 1 until powers.size) {
                val x = padding + stepX * i
                val y = padding + chartHeight * (1 - (powers[i] - minPower) / powerRange)
                path.lineTo(x, y)
                fillPath.lineTo(x, y)
            }

            // 完成填充路径
            fillPath.lineTo(padding + stepX * (powers.size - 1), CHART_HEIGHT - padding)
            fillPath.close()

            // 绘制填充区域和曲线
            canvas.drawPath(fillPath, fillPaint)
            canvas.drawPath(path, linePaint)

            // 绘制当前值点
            val lastX = padding + stepX * (powers.size - 1)
            val lastY = padding + chartHeight * (1 - (powers.last() - minPower) / powerRange)
            val dotPaint = Paint().apply {
                color = 0xFFFFFFFF.toInt()
                style = Paint.Style.FILL
                isAntiAlias = true
            }
            canvas.drawCircle(lastX, lastY, 5f, dotPaint)

            // 绘制最大值标签
            val maxLabelPaint = Paint().apply {
                color = 0xFF999999.toInt()
                textSize = 16f
                textAlign = Paint.Align.LEFT
                isAntiAlias = true
            }
            canvas.drawText("${String.format("%.0f", maxPower)}W", padding, padding - 5f, maxLabelPaint)

            return bitmap
        }

        private fun modePending(context: Context, mode: ChargeMode): PendingIntent {
            val intent = Intent(context, WidgetModeReceiver::class.java).apply {
