package com.pvpwhgame.hyperoscharge.widget

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import com.pvpwhgame.hyperoscharge.data.ModuleConfig
import com.pvpwhgame.hyperoscharge.data.ShellExecutor
import kotlinx.coroutines.*

class WidgetModeReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != "com.pvpwhgame.hyperoscharge.MODE_CHANGE") return
        val mode = intent.getStringExtra("mode") ?: return
        CoroutineScope(Dispatchers.IO).launch {
            ShellExecutor.writeFile(ModuleConfig.MODE_FILE, mode)
            delay(500)
            ChargeWidgetReceiver.refreshAll(context)
        }
    }
}

package com.pvpwhgame.hyperoscharge.data

import org.json.JSONObject

data class ChargeStatus(
    val charging: Boolean = false,
    val mode: ChargeMode = ChargeMode.BALANCE,
    val soc: Int = 0,
    val temp: Int = 0,
    val tempTier: Int = 0,
    val socTier: Int = 0,
    val finalTier: Int = 0,
    val state: Int = 0,
    val maxstate: Int = 16,
    val powerDw: Long = 0,
    val ts: Long = 0
) {
    val tempC: Float get() = temp / 10f
    val powerW: Float get() = powerDw / 10f
    val statePercent: Float get() = if (maxstate > 0) state.toFloat() / maxstate else 0f

    companion object {
        fun parse(json: String): ChargeStatus {
            val o = JSONObject(json)
            if (o.optString("error") == "no_battery_cdev") {
                return ChargeStatus()
            }
            return ChargeStatus(
                charging = o.optBoolean("charging", false),
                mode = ChargeMode.fromKey(o.optString("mode", "balance")),
                soc = o.optInt("soc", 0),
                temp = o.optInt("temp", 0),
                tempTier = o.optInt("temp_tier", 0),
                socTier = o.optInt("soc_tier", 0),
                finalTier = o.optInt("final_tier", 0),
                state = o.optInt("state", 0),
                maxstate = o.optInt("maxstate", 16),
                powerDw = o.optLong("power_dw", 0),
                ts = o.optLong("ts", 0)
            )
        }
    }
}

package com.pvpwhgame.hyperoscharge.data

data class HistoryPoint(
    val ts: Long,
    val charging: Int,
    val soc: Int,
    val temp: Int,
    val state: Int,
    val maxstate: Int,
    val mode: String,
    val powerDw: Long
) {
    val tempC: Float get() = temp / 10f
    val powerW: Float get() = powerDw / 10f
    val statePercent: Float get() = if (maxstate > 0) state.toFloat() / maxstate else 0f

    companion object {
        fun parseCsv(text: String): List<HistoryPoint> {
            return text.trim().split("\n")
                .filter { it.isNotBlank() }
                .mapNotNull { line ->
                    val parts = line.split(",")
                    if (parts.size >= 7) {
                        HistoryPoint(
                            ts = parts[0].toLongOrNull() ?: return@mapNotNull null,
                            charging = parts[1].toIntOrNull() ?: 0,
                            soc = parts[2].toIntOrNull() ?: 0,
                            temp = parts[3].toIntOrNull() ?: 0,
                            state = parts[4].toIntOrNull() ?: 0,
                            maxstate = parts[5].toIntOrNull() ?: 16,
                            mode = parts[6],
                            powerDw = parts.getOrNull(7)?.toLongOrNull() ?: 0
                        )
                    } else null
                }
        }
    }
}
